insert into public.problem_evaluation_packages (problem_version_id, reference_answer, reasoning_rubric, acceptable_alternative_approaches, misconceptions, hint_ladder, completion_criteria, evaluation_examples)
select 'pv-drone-1', 'Train the history encoder jointly with an action-conditioned dynamics predictor. Given the current state, action, and latent z inferred only from earlier history, predict the next state or a short future trajectory. Minimize a suitable state-transition prediction loss across diverse simulated dynamics. Different masses, motor strengths, and drag change the effect of the same action, so this objective creates pressure for z to retain information about those effects. Keep the target outside the encoder''s input window to avoid leakage, and compare against predictors that ignore or shuffle z to check for shortcuts. A good prediction loss alone does not establish control usefulness: evaluate closed-loop adaptation on held-out physical parameter combinations, with a no-adaptation baseline. z need not uniquely identify every physical parameter; it must preserve task-relevant distinctions that the history makes identifiable.', '[{"id":"drone_dynamics","label":"Identify the dynamics gap","description":"Connect deployment failure to changes in action-to-state transitions.","weight":1,"prerequisiteNodeIds":[],"sufficientEvidenceDescription":"Explains how a changed payload, motor, or drag changes a state transition under the same action."},{"id":"drone_signal","label":"Justify a learning signal","description":"Propose an objective whose solution benefits from dynamics information.","weight":3,"prerequisiteNodeIds":[],"sufficientEvidenceDescription":"Explains conditional transition prediction, control-relevant identification, or another grounded objective and why z is needed.","notes":"Do not require the words forward model. A task-driven objective with a valid information argument can satisfy this node."},{"id":"drone_shortcuts","label":"Address identifiability and shortcuts","description":"Distinguish a useful context representation from a reconstruction shortcut.","weight":2,"prerequisiteNodeIds":[],"sufficientEvidenceDescription":"Mentions sufficient excitation/history, target leakage, variation in dynamics, or a test showing z matters."},{"id":"drone_validation","label":"Validate adaptation","description":"Test downstream utility on dynamics not seen during training.","weight":2,"prerequisiteNodeIds":["drone_signal"],"sufficientEvidenceDescription":"Proposes held-out dynamics and a controlled comparison of adaptation enabled versus disabled."}]'::jsonb, '[{"id":"drone_task_driven","description":"Train the context encoder through a control objective across randomized dynamics, then show by ablation that history-dependent adaptation improves held-out control performance.","rubricNodeIds":["drone_signal","drone_validation"]},{"id":"drone_privileged_teacher","description":"Learn a privileged dynamics embedding in simulation and distill it into a history encoder, checking that the embedding captures control-relevant variation and transfers to unseen dynamics.","rubricNodeIds":["drone_signal","drone_shortcuts"]}]'::jsonb, '[{"id":"drone_reconstruct_only","title":"Reconstruction guarantees dynamics","description":"Reconstructing the current observation can preserve appearance while ignoring how actions change state.","relatedRubricNodeIds":["drone_signal"],"detectionNotes":"Flag only when reconstruction alone is claimed to guarantee dynamics; do not reject auxiliary reconstruction losses."},{"id":"drone_parameter_identity","title":"Every physical parameter must be recovered","description":"Task-relevant dynamics may be sufficient even when individual parameters are not identifiable.","relatedRubricNodeIds":["drone_shortcuts"]}]'::jsonb, '[{"id":"hint-drone-1","targetRubricNodeId":"drone_signal","level":1,"text":"Think about what changes after the same state and action are applied under different physical dynamics."},{"id":"hint-drone-2","targetRubricNodeId":"drone_signal","level":2,"text":"What could you ask a model to predict that depends on both the chosen action and the dynamics?"},{"id":"hint-drone-3","targetRubricNodeId":"drone_validation","level":3,"text":"Compare a predictor using z with one that ignores it, then test the controller on held-out dynamics."}]'::jsonb, '{"requiredNodeIds":["drone_dynamics","drone_signal"],"alternativeNodeGroups":[["drone_shortcuts"],["drone_validation"]],"description":"Require a justified dynamics-relevant signal and at least one defensible safeguard or validation argument. Accept multiple valid routes through the rubric."}'::jsonb, '[{"id":"example-drone-reconstruction","response":"Maybe the encoder should reconstruct the current observation.","expectedResult":{"rubricAssessments":[{"rubricNodeId":"drone_dynamics","status":"unseen","evidence":[]},{"rubricNodeId":"drone_signal","status":"uncertain","evidence":[{"messageId":"example-message-1","quote":"reconstruct the current observation"}],"explanation":"Ask whether reconstruction is the only objective before assuming a misconception."}],"detectedMisconceptions":[],"contradictions":[],"needsEscalation":false,"escalationReason":null,"feedbackCategory":"clarification_needed"}}]'::jsonb
where not exists (select 1 from public.problem_evaluation_packages where problem_version_id = 'pv-drone-1')
on conflict do nothing;

insert into public.problem_evaluation_packages (problem_version_id, reference_answer, reasoning_rubric, acceptable_alternative_approaches, misconceptions, hint_ladder, completion_criteria, evaluation_examples)
select 'pv-camera-1', 'Collect independently labeled, paired images from both cameras and compare error rates on the same items. Check resolution, color response, focus, compression, crop, and preprocessing rather than relying on average brightness. Inspect score distributions and false positives by defect type. Change one factor at a time; for example, align the preprocessing pipeline and compare again. Only choose recalibration, data collection, or retraining after the experiment identifies the failure mechanism. Evaluate the intervention on a held-out sample from both cameras.', '[{"id":"pv-camera-1-r1","label":"Reasoning point 1","description":"Hold the physical item constant when comparing cameras.","weight":1,"prerequisiteNodeIds":[],"sufficientEvidenceDescription":"Hold the physical item constant when comparing cameras."},{"id":"pv-camera-1-r2","label":"Reasoning point 2","description":"Distinguish preprocessing, distribution shift, and threshold effects.","weight":1,"prerequisiteNodeIds":[],"sufficientEvidenceDescription":"Distinguish preprocessing, distribution shift, and threshold effects."},{"id":"pv-camera-1-r3","label":"Reasoning point 3","description":"Validate the selected intervention on independent samples.","weight":1,"prerequisiteNodeIds":[],"sufficientEvidenceDescription":"Validate the selected intervention on independent samples."}]'::jsonb, '[{"id":"pv-camera-1-alt1","description":"A staged rollback or controlled camera crossover can isolate a deployment change.","rubricNodeIds":["pv-camera-1-r1"]},{"id":"pv-camera-1-alt2","description":"A calibrated uncertainty or abstention policy may be a temporary response while collecting reliable labels.","rubricNodeIds":["pv-camera-1-r1"]}]'::jsonb, '[{"id":"pv-camera-1-mc1","title":"One metric proves the explanation","description":"An aggregate measurement alone does not establish the mechanism or task utility.","relatedRubricNodeIds":["pv-camera-1-r1"]}]'::jsonb, '[{"id":"pv-camera-1-hint1","targetRubricNodeId":"pv-camera-1-r1","level":1,"text":"Which comparison would keep the physical item fixed while changing only the camera?"}]'::jsonb, '{"requiredNodeIds":["pv-camera-1-r1"],"alternativeNodeGroups":[["pv-camera-1-r2"],["pv-camera-1-r3"]],"description":"Explain the core distinction and support it with an experiment or a relevant limitation."}'::jsonb, '[{"id":"pv-camera-1-example1","response":"The average metric looks good, so the model must be useful.","expectedResult":{"rubricAssessments":[{"rubricNodeId":"pv-camera-1-r1","status":"partial","evidence":[{"messageId":"pv-camera-1-message1","quote":"average metric"}]}],"detectedMisconceptions":[],"contradictions":[],"needsEscalation":false,"escalationReason":null,"feedbackCategory":"clarification_needed"}}]'::jsonb
where not exists (select 1 from public.problem_evaluation_packages where problem_version_id = 'pv-camera-1')
