insert into public.problem_evaluation_packages (problem_version_id, reference_answer, reasoning_rubric, acceptable_alternative_approaches, misconceptions, hint_ladder, completion_criteria, evaluation_examples)
select 'pv-representation-1', 'A useful representation retains the distinctions needed for the target task and makes them accessible to the downstream model. Equal vector sizes do not imply equal information or accessibility. Reconstruction can prioritize background, texture, or other high-variance details while losing a small task-relevant signal. Compare downstream performance under controlled data and model capacity, test generalization, and use interventions to inspect which nuisance factors affect the representation. Compression and reconstruction can be useful tools, but neither alone establishes task sufficiency.', '[{"id":"pv-representation-1-r1","label":"Reasoning point 1","description":"Utility depends on the downstream task.","weight":1,"prerequisiteNodeIds":[],"sufficientEvidenceDescription":"Utility depends on the downstream task."},{"id":"pv-representation-1-r2","label":"Reasoning point 2","description":"Reconstruction and task losses can favor different information.","weight":1,"prerequisiteNodeIds":[],"sufficientEvidenceDescription":"Reconstruction and task losses can favor different information."},{"id":"pv-representation-1-r3","label":"Reasoning point 3","description":"Evaluate usefulness with controlled downstream comparisons.","weight":1,"prerequisiteNodeIds":[],"sufficientEvidenceDescription":"Evaluate usefulness with controlled downstream comparisons."}]'::jsonb, '[{"id":"pv-representation-1-alt1","description":"Describe task sufficiency or information bottlenecks without asserting that an unsupervised metric guarantees downstream quality.","rubricNodeIds":["pv-representation-1-r1"]},{"id":"pv-representation-1-alt2","description":"Use nuisance invariance and linear-probe limitations to explain why equal dimension is not enough.","rubricNodeIds":["pv-representation-1-r1"]}]'::jsonb, '[{"id":"pv-representation-1-mc1","title":"One metric proves the explanation","description":"An aggregate measurement alone does not establish the mechanism or task utility.","relatedRubricNodeIds":["pv-representation-1-r1"]}]'::jsonb, '[{"id":"pv-representation-1-hint1","targetRubricNodeId":"pv-representation-1-r1","level":1,"text":"Could an encoder preserve the background very well while discarding a detail needed for the task?"}]'::jsonb, '{"requiredNodeIds":["pv-representation-1-r1"],"alternativeNodeGroups":[["pv-representation-1-r2"],["pv-representation-1-r3"]],"description":"Explain the core distinction and support it with an experiment or a relevant limitation."}'::jsonb, '[{"id":"pv-representation-1-example1","response":"The average metric looks good, so the model must be useful.","expectedResult":{"rubricAssessments":[{"rubricNodeId":"pv-representation-1-r1","status":"partial","evidence":[{"messageId":"pv-representation-1-message1","quote":"average metric"}]}],"detectedMisconceptions":[],"contradictions":[],"needsEscalation":false,"escalationReason":null,"feedbackCategory":"clarification_needed"}}]'::jsonb
